WITH rollup_totals AS (SELECT p.city, p.country, s.brand, COUNT(*) AS rows_total, SUM(s.stock_qty) AS total_stock_qty, MIN(s.price) AS min_price FROM products s INNER JOIN suppliers p ON s.supplier_id = p.id GROUP BY GROUPING SETS ((p.city, p.country, s.brand), (p.city, p.country), (p.city))) SELECT country, brand, rows_total, total_stock_qty, min_price, CASE WHEN brand RLIKE '^(Initech|Stark)$' THEN 'GROUP_A' ELSE 'CORE' END AS brand_zone FROM rollup_totals;
